pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testRegression_property() public {
        Reverter reverter = new Reverter();
        address[] memory tos = new address[](1);
        tos[0] = address(0x1);

        bool ok;
        try c.transfer(address(0x2), address(reverter), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "transfer should have reverted due to failed inner call");
    }
}

contract Reverter {
    fallback() external payable {
        revert("transferFrom failed");
    }
}
